module critical_elements (\n    input wire clk,\n    input wire rst_n,\n    input wire start,\n    input wire [4:0] n,\n    input wire [7:0] arr [15:0],\n    output reg [7:0] critical [15:0],\n    output reg [4:0] critical_count,\n    output reg done\n);\n\n    // Parameters\n    localparam MAX_N = 16;\n    localparam DATA_WIDTH = 8;\n    localparam COUNT_WIDTH = 5;\n\n    // Main FSM states\n    localparam [4:0] IDLE          = 5'd0;\n    localparam [4:0] START_ORIG_LIS = 5'd1;\n    localparam [4:0] WAIT_ORIG_LIS  = 5'd2;\n    localparam [4:0] LOOP_I         = 5'd3;\n    localparam [4:0] BUILD_TEMP_INIT = 5'd4;\n    localparam [4:0] BUILD_TEMP_LOOP = 5'd5;\n    localparam [4:0] START_TEMP_LIS  = 5'd6;\n    localparam [4:0] WAIT_TEMP_LIS   = 5'd7;\n    localparam [4:0] COMPARE_LIS     = 5'd8;\n    localparam [4:0] INCREMENT_I     = 5'd9;\n    localparam [4:0] SORT_INIT       = 5'd10;\n    localparam [4:0] SORT_PASS       = 5'd11;\n    localparam [4:0] SORT_SWAP_CECK  = 5'd12;\n    localparam [4:0] SORT_SWAP       = 5'd13;\n    localparam [4:0] SORT_NEXT_PASS  = 5'd14;\n    localparam [4:0] OUTPUT_DONE     = 5'd15;\n\n    // DP FSM states\n    localparam [3:0] DP_IDLE        = 4'd0;\n    localparam [3:0] DP_INIT        = 4'd1;\n    localparam [3:0] DP_MAIN        = 4'd2;\n    localparam [3:0] DP_UPDATE      = 4'd3;\n    localparam [3:0] DP_NEXT_J      = 4'd4;\n    localparam [3:0] DP_NEXT_I      = 4'd5;\n    localparam [3:0] DP_FINDMAX     = 4'd6;\n    localparam [3:0] DP_DONE        = 4'd7;\n\n    // Main FSM registers\n    reg [4:0] state, next_state;\n    reg [7:0] orig_arr [15:0];\n    reg [7:0] temp_arr [15:0];\n    reg [4:0] i, j, k;\n    reg [4:0] pass_idx, swap_idx;\n    reg [7:0] orig_lis, temp_lis;\n    reg [4:0] critical_idx;\n    reg loop_finished;\n    reg [7:0] max_val;\n    reg [4:0] max_idx;\n    reg [7:0] store_element;\n    reg start_dp;\n    reg dp_done;\n    reg [7:0] curr_arr [15:0];\n    reg [4:0] curr_len;\n\n    // DP FSM registers\n    reg [3:0] dp_state, next_dp_state;\n    reg [4:0] dp_i, dp_j;\n    reg [7:0] dp [15:0];\n    reg [7:0] max_dp;\n\n    // Main FSM next state logic\n    always @(*) begin\n        next_state = state;\n        case (state)\n            IDLE:          if (start) next_state = START_ORIG_LIS;\n            START_ORIG_LIS: next_state = WAIT_ORIG_LIS;\n            WAIT_ORIG_LIS:  if (dp_done) next_state = LOOP_I;\n            LOOP_I:         if (i < n) next_state = BUILD_TEMP_INIT; else next_state = SORT_INIT;\n            BUILD_TEMP_INIT: next_state = BUILD_TEMP_LOOP;\n            BUILD_TEMP_LOOP: if (j >= n) next_state = START_TEMP_LIS;\n            START_TEMP_LIS:  next_state = WAIT_TEMP_LIS;\n            WAIT_TEMP_LIS:   if (dp_done) next_state = COMPARE_LIS;\n            COMPARE_LIS:     next_state = INCREMENT_I;\n            INCREMENT_I:     next_state = LOOP_I;\n            SORT_INIT:       if (critical_idx > 5'd1) next_state = SORT_PASS;\n                             else if (critical_idx != 5'd0) next_state = OUTPUT_DONE;\n                             else next_state = OUTPUT_DONE;\n            SORT_PASS:       next_state = SORT_SWAP_CECK;\n            SORT_SWAP_CECK:  if (swap_idx < critical_idx - pass_idx - 5'd1) next_state = SORT_SWAP;\n                             else next_state = SORT_NEXT_PASS;\n            SORT_SWAP:       next_state = SORT_SWAP_CECK;\n            SORT_NEXT_PASS:  if (pass_idx < critical_idx - 5'd2) next_state = SORT_PASS;\n                             else next_state = OUTPUT_DONE;\n            OUTPUT_DONE:     next_state = IDLE;\n            default:         next_state = IDLE;\n        endcase\n    end\n\n    // DP FSM next state logic\n    always @(*) begin\n        next_dp_state = dp_state;\n        case (dp_state)\n            DP_IDLE:   if (start_dp) next_dp_state = DP_INIT;\n            DP_INIT:   next_dp_state = DP_MAIN;\n            DP_MAIN:   if (dp_i < curr_len) begin\n                           if (dp_j < dp_i) next_dp_state = DP_UPDATE;\n                           else next_dp_state = DP_NEXT_I;\n                       end else next_dp_state = DP_FINDMAX;\n            DP_UPDATE: next_dp_state = DP_NEXT_J;\n            DP_NEXT_J: next_dp_state = DP_MAIN;\n            DP_NEXT_I: next_dp_state = DP_MAIN;\n            DP_FINDMAX: next_dp_state = DP_DONE;\n            DP_DONE:   next_dp_state = DP_IDLE;\n            default:   next_dp_state = DP_IDLE;\n        endcase\n    end\n\n    // Main FSM sequential logic\n    integer idx;\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            done <= 1'b0;\n            critical_count <= 5'd0;\n            critical_idx <= 5'd0;\n            for (idx = 0; idx < MAX_N; idx = idx + 1) begin\n                orig_arr[idx] <= 8'd0;\n                temp_arr[idx] <= 8'd0;\n                critical[idx] <= 8'd0;\n            end\n            i <= 5'd0;\n            j <= 5'd0;\n            k <= 5'd0;\n            pass_idx <= 5'd0;\n            swap_idx <= 5'd0;\n            orig_lis <= 8'd0;\n            temp_lis <= 8'd0;\n            start_dp <= 1'b0;\n            loop_finished <= 1'b0;\n        end else begin\n            state <= next_state;\n            case (state)\n                IDLE: begin\n                    done <= 1'b0;\n                    critical_count <= 5'd0;\n                    critical_idx <= 5'd0;\n                    if (start) begin\n                        for (idx = 0; idx < MAX_N; idx = idx + 1)\n                            orig_arr[idx] <= (idx < n) ? arr[idx] : 8'd0;\n                    end\n                end\n\n                START_ORIG_LIS: begin\n                    // Setup DP computation for original array\n                    curr_len <= n;\n                    for (idx = 0; idx < MAX_N; idx = idx + 1)\n                        curr_arr[idx] <= orig_arr[idx];\n                    start_dp <= 1'b1;\n                end\n\n                WAIT_ORIG_LIS: begin\n                    start_dp <= 1'b0;\n                    if (dp_done) begin\n                        orig_lis <= max_dp;\n                        i <= 5'd0;\n                    end\n                end\n\n                BUILD_TEMP_INIT: begin\n                    j <= 5'd0;\n                    k <= 5'd0;\n                end\n\n                BUILD_TEMP_LOOP: begin\n                    if (j < n) begin\n                        if (j != i) begin\n                            temp_arr[k] <= orig_arr[j];\n                            k <= k + 5'd1;\n                        end\n                        j <= j + 5'd1;\n                    end\n                end\n\n                START_TEMP_LIS: begin\n                    // Setup DP for temp array\n                    curr_len <= n - 5'd1;\n                    for (idx = 0; idx < MAX_N; idx = idx + 1)\n                        curr_arr[idx] <= temp_arr[idx];\n                    start_dp <= 1'b1;\n                end\n\n                COMPARE_LIS: begin\n                    if (temp_lis < orig_lis) begin\n                        critical[critical_idx] <= orig_arr[i];\n                        critical_idx <= critical_idx + 5'd1;\n                    end\n                end\n\n                INCREMENT_I: begin\n                    i <= i + 5'd1;\n                end\n\n                SORT_INIT: begin\n                    critical_count <= critical_idx;\n                    pass_idx <= 5'd0;\n                end\n\n                SORT_PASS: begin\n                    swap_idx <= 5'd0;\n                end\n\n                SORT_SWAP: begin\n                    if (critical[swap_idx] > critical[swap_idx + 5'd1]) begin\n                        store_element <= critical[swap_idx];\n                        critical[swap_idx] <= critical[swap_idx + 5'd1];\n                        critical[swap_idx + 5'd1] <= store_element;\n                    end\n                    swap_idx <= swap_idx + 5'd1;\n                end\n\n                SORT_NEXT_PASS: begin\n                    pass_idx <= pass_idx + 5'd1;\n                end\n\n                OUTPUT_DONE: begin\n                    done <= 1'b1;\n                end\n            endcase\n        end\n    end\n\n    // DP FSM sequential logic\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            dp_state <= DP_IDLE;\n            max_dp <= 8'd0;\n        end else begin\n            dp_state <= next_dp_state;\n            case (dp_state)\n                DP_IDLE: begin\n                    max_dp <= 8'd0;\n                    for (idx = 0; idx < MAX_N; idx = idx + 1)\n                        dp[idx] <= 8'd0;\n                end\n\n                DP_INIT: begin\n                    dp_i <= 5'd1;\n                    dp_j <= 5'd0;\n                    for (idx = 0; idx < MAX_N; idx = idx + 1)\n                        dp[idx] <= 8'd1;\n                end\n\n                DP_UPDATE: begin\n                    if (curr_arr[dp_j] < curr_arr[dp_i]) begin\n                        if (dp[dp_j] + 8'd1 > dp[dp_i]) begin\n                            dp[dp_i] <= dp[dp_j] + 8'd1;\n                        end\n                    end\n                end\n\n                DP_NEXT_J: begin\n                    dp_j <= dp_j + 5'd1;\n                end\n\n                DP_NEXT_I: begin\n                    dp_j <= 5'd0;\n                    dp_i <= dp_i + 5'd1;\n                end\n\n                DP_FINDMAX: begin\n                    max_dp <= 8'd0;\n                    for (idx = 0; idx < MAX_N; idx = idx + 1) begin\n                        if (dp[idx] > max_dp && idx < curr_len) begin\n                            max_dp <= dp[idx];\n                        end\n                    end\n                end\n\n                DP_DONE: begin\n                    dp_done <= 1'b1;\n                end\n\n                DP_IDLE: begin\n                    dp_done <= 1'b0;\n                end\n            endcase\n        end\n    end\nendmodule